import"./chunk-chunk.WKASLGNO.js";var v=[{v:"v3.4.0",i:["新增 · 词库精简：初始仅保留高考3500词、高考总汇、688高频词、985核心词汇四本，其余词库改为按需下载","新增 · 「我的」页新增扩展词库下载区，9 本内置扩展词库逐本下载/移除，数据随应用内置无需联网，状态记在本机","新增 · 词库重命名：在词库管理页可对任意词库（内置/下载/自建）重命名，名字重启后保留","优化 · 仅加载已下载词库的数据，启动更快、占用更少；删除下载词库会同步清除下载标记，避免重启后又出现"]},{v:"v3.3.0",i:["优化 · 按考频汇编词库新增「自选词库」，可勾选具体要汇编的词库，不再只能全部或背诵词库","新增 · 汇编时可自定义新词库名称，留空则自动生成；创建成功后弹窗明确提示词数、阈值与来源","修复 · 词库名内嵌的固定数量与真实数量对不上（如褒义词92个/熟词生义150个），改为名称不内嵌数字，数量由列表按实际实时显示","修复 · 导入页状态提示重复显示两行的问题","修复 · 关联词区域「已就绪」状态写死不随加载变化的问题；背诵义项范围按钮高亮反转问题"]},{v:"v3.2.0",i:["新增 · 每个中文义项显示高考真题考查次数，点击可展开具体出处（年份·卷别·题号·真题原句），全部来自真实真题、可追溯","升级 · 义项考频基于内置 200 篇 2008-2026 高考真题阅读挖空点逐条提取，共 1016 条真题证据，非官方统计、无出处不标注","保留 · 高频核心义 / 熟词生义 / 一般义项分类与背诵三选项（高考频中文/熟词生义/随机）不变"]},{v:"v3.1.0",i:["新增 · 显示每个单词不同中文意思的高考考查类别（高频核心义 / 熟词生义 / 一般义项），词级真题次数照实显示","新增 · 背诵页可切换「高考频中文 / 熟词生义 / 随机义项」三种考查范围，按类别出题、判分一致","新增 · 导入页「按考频汇编新词库」：扫描全部词库（含后续导入的），自定义真题次数阈值（无档位限制），一键汇编成新词库","优化 · 入库时剔除明确非高考的义项，只保留核心义与熟词生义；无高考数据的导入词保留原义项，不臆断删除","说明 · 官方不发布逐义项考次，故义项只标类别、不编造每个意思的具体次数"]},{v:"v3.0.1",i:["修复 · 耳机 / 蓝牙的播放、暂停、切词按键现在通过系统媒体会话正式绑定，像控制音乐软件一样控制听读","修复 · 中文发音期间保持音频会话活跃，后台播放时耳机按键不再失效","优化 · 网页版耳机控制按键提前注册，打开即可用"]},{v:"v3.0.0",i:["修复 · 听读在 vivo / OPPO 等手机系统「正在播放」里找不到：补齐系统识别媒体源所需的封面图标与媒体信息，现在会像音乐软件一样出现在系统媒体中心","新增 · 耳机 / 蓝牙首次按播放键可直接唤醒听读，无需先打开应用","优化 · 播放时更明确地以「媒体音频」身份登记，锁屏与下拉面板的控制更稳定"]},{v:"v2.99.0",i:["新增 · 听读接入手机系统媒体中心：锁屏、车机、蓝牙耳机、智能手表都能识别为正在播放的音频","新增 · 手机像识别音乐软件一样识别本应用，系统媒体控制可统一暂停、继续、切词","优化 · 听读不再只是通知栏控制卡片，而是系统认可的音频播放源"]},{v:"v2.96.0",i:["修复 · 切换词库后关联词串数据：内容长度相同但内容不同的词库会显示上一个词库的关联词与错误释义，现按词库内容识别，词库一变立即刷新","修复 · 开启「自动跳转」后连答几题或手动翻页会连跳、乱跳：改为同一时刻只有一个有效跳转，翻页即作废旧跳转","修复 · 后台保存监听重复注册导致的重复保存","修复 · 网页版更新提示可能把更旧版本误报为新版本：改为按版本号大小比较，只有确实更新才提示"]},{v:"v2.95.0",i:["修复 · 点击「用内置算法检索当前词库」会卡死：检索改为分片进行、显示进度且可随时取消，超大词库也能顺畅使用","修复 · 导入页说明卡片在窄屏上文字与按钮重叠、底部被导航栏挡住","修复 · 删除/清空/重命名等确认框弹出系统原生对话框（暴露 file 网址标题、绿色系统按钮和裂图）：统一改为应用内弹窗","优化 · 全局排查同类问题：耗时计算让出界面、统一应用内弹窗、修复相对路径裂图，并加发布前检查防止再犯"]},{v:"v2.94.0",i:["调整 · 移除「设置 → 数据来源说明」里纯技术内部内容（考频交叉校验值、开源项目引用、机构引述等），只保留用户看得懂的说明","调整 · 高考考频、真题文章、联网补全、关联词与导出、初中词库等面向用户的来源说明保留"]},{v:"v2.93.0",i:["新增 · 「设置」改为独立整屏界面：「我的」页只留学习简介、设置入口和初中词库下载卡片，设置项不再堆在「我的」页里","调整 · 设置界面顶部有返回按钮和标题，底部导航栏自动隐藏，与「我的」页彻底分开","修复 · 返回按钮和手机返回键都先回到「我的」页，不会直接退出应用"]},{v:"v2.92.0",i:["修复 · 彻底解决闪退、打不开、无故刷新：启动不再下载并整页替换界面，只加载安装包内置且验证过的页面，历史坏缓存自动清除","新增 · 启动自愈守卫：连续两次启动异常自动进安全模式，跳过耗资源的后台加载","新增 · 不依赖界面的恢复面板：页面起不来时可直接「安全模式启动 / 清数据重启 / 重新加载 / 下载安装包」自救","优化 · 初中词库改为空闲时分批加载，不再一次生成全部词条导致低端机卡死"]},{v:"v2.91.0",i:["修复 · 闪退打不开：初中词库不再在启动时一次性加载，避免低端机内存不足闪退","修复 · 无故刷新界面：改为只提示「有新版本」，由你主动点击才刷新","修复 · 无法更新：更新检查加超时，移除会误报「必须装新版」的旧逻辑","调整 · 初中必考词(1902) / 初中阅读词汇(406) 改为「我的」页按需下载：默认不占词库列表，点下载后才可用，可随时移除，无需联网"]},{v:"v2.90.0",i:["新增 · 初中扩展词库：初中必考词(1902词，按中考词频排序) 和 初中阅读词汇(406词)，可在词库选择 / 背诵 / 听读 / 导出中自由选用","新增 · 新词库与其他词库规格完全一致：中文释义、词性、考点、例句、考频徽标、关联词、发音、按考频导出一样不少","新增 · 「我的 → 设置 → 数据来源说明」增加初中扩展词库来源说明，如实标注官方只给范围、不逐词标释义考频"]},{v:"v2.89.0",i:["新增 · 「我的」页新增醒目「设置」入口，默认收起，点开才显示全部设置与来源说明","调整 · 学习信息（首次使用、日期、总词库、总词汇量）提为常驻「学习概览」卡片，一屏可见","优化 · 设置展开状态记在本机，下次进入保持上次选择"]},{v:"v2.88.0",i:["新增 · 考频数据来源核验：核对教育部课标、北京教育考试院建议与真题语料方法，确认 130+ 份真题/模拟语料来源真实可核验","优化 · 考频口径更诚实：如实说明课标只给词范围、官方不发布逐词次数、语料含模拟卷，不冒充官方考频","调整 · 「我的」页新增考频数据真实性核验说明（来源＋结论）"]},{v:"v2.87.0",i:["优化 · 「我的」页设置区重排，分组更清晰、布局更紧凑；数据来源说明改为可折叠","调整 · 纯开关类设置（自动发音、护眼、艾宾浩斯、答后考点、优先高频、联网补全、答题音效等）全部改为按钮开关，点按即切换、自动保存","删除 · 移除「清理不存在的词库」冗余按钮"]},{v:"v2.86.0",i:["新增 · 导出词库默认按高考考频顺序（高频→中频→低频），与「优先背诵高频词」同一口径；导出面板可切换「按考频 / 词库原顺序」","优化 · 内置关联词检索更准：同源词族按匹配强度排序、易混词排除同源派生词，命中词库补真实中文释义","优化 · 考频标记更诚实：真题实测次数优先，联网词频只给等级、不编造次数，没取到标「待补全」","删除 · AI 大模型识别功能（服务商配置、API Key、AI 标注徽标等），内置解析照常可用、无需任何配置"]},{v:"v2.85.0",i:["新增 · 免密钥联网补全：内置词表没收录的词（含自行导入生词）自动获取通用语料词频与同义/反义/语义关联词，无需配置","新增 · 导入词也有高/中/低频徽标与关联词，明确标注「联网参考」，不伪装成高考真题次数","新增 · 「我的 → 设置」增加联网补全开关、立即补全全部、清除缓存与来源说明；结果存本机、离线可用","优化 · 全局界面细节：统一按钮 / 输入框焦点与悬浮反馈、细滚动条、徽标与卡片层次、护眼一致性，不改布局尺寸"]},{v:"v2.84.0",i:["新增 · 背诵页「真题文章」模式：一篇高考真题原文多个单词一起作答，可选「选项」或「填空」","新增 · 文章取自 2008-2026 历年高考真题阅读原文，逐字保留并标注年份卷别","新增 · 填空只做宽松语义判断，大致意思相符即算对，答后显示正确单词与释义","优化 · 「我的」页把分散的设置与反馈合并为一个集中设置区，并移到页面顶部"]},{v:"v2.83.0",i:["新增 · 全库单词标注高频 / 中频 / 低频 / 基础四档，背诵页、词库列表、详情页显示等级与真题出现次数","新增 · 近五年真题高频词单独显示「近五年 N 次」，数据来自 130+ 份真题语料逐词统计","新增 · 「优先背诵高频词」开关，开启后高频词优先、同档按真题次数推进","优化 · 未被真题收录的词次数显示「—」，按考纲与通用词频标等级，不编造次数"]},{v:"v2.82.1",i:["优化 · 答题选项恢复原来单列大按钮，题卡、题目、进度区与答后面板恢复原间距","优化 · 仅保留背诵页六个设置开关的紧凑排布","调整 · 「答题后显示全部考点」开关保持不变"]},{v:"v2.82.0",i:["新增 · 「答题后显示全部考点」开关：开启后答完题展示该词全部考点、搭配、词族与例句，关闭只看其他选项中文","优化 · 背诵页选项改两列紧凑胶囊按钮，题目与选项一打开即可完整看到","优化 · 背诵页快捷按钮、进度区与题卡纵向空间收紧，减少滚动"]},{v:"v2.81.3",i:["优化 · 补齐 985 核心词汇遗漏 / 残缺的词性（如 billion、million 标数词，ought、would 标助动词）","优化 · 高考3500 词库词性标签剥离误混入的音标，只显示干净词性","优化 · 所有词库与导入数据入库时统一校验词性，缺词性不再显示占位字样"]},{v:"v2.81.2",i:["优化 · 例句语境模式改用真实高考真题双语例句（英文原句高亮目标词，答题后揭示译文），优先近五年真题高频词","调整 · 自动发音开关回到「我的」页，各模式快捷按钮数量保持一致","优化 · 护眼模式按视觉工效学重做低蓝光暖色主题（暖纸色背景、暖近黑文字、暖琥珀主色）"]},{v:"v2.81.1",i:["修复 · 更新检测：修正版本号匹配，旧安装包能正确收到新版本提示（此前部分旧版版本撞车收不到更新）","调整 · 自动发音开关移到背诵页快捷栏，做题时随时开关"]},{v:"v2.81.0",i:["新增 · 自动发音开关移到背诵页快捷栏，做题时随时开关","优化 · 「我的」页去冗余：背诵模式、难度、自动掌握、自动跳转、自动发音、音量键翻页都在背诵页快捷栏调"]},{v:"v2.80.0",i:["新增 · 护眼模式开关（暖色低蓝光），在「我的 → 设置 → 学习辅助与反馈」开启","新增 · 艾宾浩斯记忆法开关：按遗忘曲线安排复习，到期词优先出现","新增 · 答题音效：答对 / 答错用不同音效，各 4 套可试听切换，带总开关，离线可用","新增 · 例句语境背诵模式：在英文搭配语境中判断义项，高亮目标词、隐去中文答案"]},{v:"v2.79.0",i:["新增 · 网页版首屏只加载轻量骨架，不再一口气下载全部词库","新增 · 词库分片下载失败给出原因和「重试」按钮，不用刷新整页","新增 · 网页版内置图标和更新清单，少两次多余请求","优化 · 词库「加载中」「加载失败」分开显示；热更包压缩，下载体积更小"]},{v:"v2.78.0",i:["新增 · 背诵页可开关「音量键翻页」，音量上 / 下键切换上一个 / 下一个词","新增 · 释义以高考高频义项为主，选项只显示最常用中文","新增 · 听读联网时在线播放，不再把每个词音频存到手机","优化 · 四选一自动去重，困难模式不再出现两个几乎一样的中文","优化 · 全库释义清理，去掉与高考无关内容；词形变化、缩略语注释不再混进释义","优化 · 老版本遗留听读音频缓存自动清理一次"]}];export{v as BUILTIN_CHANGELOG};
